package game.sanguo.core;
import java.nio.file.*;import java.util.*;
public final class ActualTurnFailureProbe{public static void main(String[]args)throws Exception{Path p=Path.of(args[0]);byte[] raw=Files.readAllBytes(p);World w=SaveCodec.decode(raw);System.out.println("SHA="+PcCommandCapacityPolicy.hex(java.security.MessageDigest.getInstance("SHA-256").digest(raw))+" source="+w.scenarioId+" player="+w.player+" turn="+w.turn+" campaignRng="+w.strategy.getRandomState()+" activeContest="+w.contests.current());for(var s:w.war.structures)if(s.owner==w.player)System.out.println("structure="+s.kind+" cell="+s.hex+" hp="+s.hp+" complete="+s.complete+" builder="+s.builder);var result=w.nextTurn();System.out.println("NEXT ok="+result.ok+" message="+result.message+" turn="+w.turn);if(!Arrays.equals(raw,Files.readAllBytes(p)))throw new AssertionError("original actual evidence changed");}}
